def normalized(value):
    value = unicodedata.normalize("NFKD", str(value or "")).lower()
    value = "".join(c for c in value if not unicodedata.combining(c))
    return " ".join(re.sub(r"[^a-z0-9]+", " ", value).split())
def in_tuscany(value):
    loc = normalized(value)
    if not loc or "da verificare" in loc or "da confermare" in loc:
        return False
    return any((" " + city + " ") in (" " + loc + " ") for city in LOCALITIES)
if __name__ == "__main__":
    assert all(in_tuscany(p) for p in PROVINCES)
    assert in_tuscany("Sesto Fiorentino, FI") and in_tuscany("Pontassieve")
    assert not in_tuscany("Milano, Lombardia") and not in_tuscany("Italia / EMEA")
    assert not in_tuscany("Firenze Toscana (da verificare)")
